//! Private, bounded records with redo-before-publication transactions. No whole-job JSON or active-job pruning.
use super::{types::Job, Result, MAX_RECORD};
use serde::{de::DeserializeOwned,Deserialize,Serialize};
use serde_json::{json,Value};
use std::{fs,io::{Read,Write},path::{Path,PathBuf}};
use sha2::{Digest,Sha256};

pub fn hash(bytes:&[u8])->String {format!("{:x}",Sha256::digest(bytes))}
pub fn id()->String{uuid::Uuid::new_v4().to_string()}
pub fn safe_id(s:&str)->Result<()> {if s.is_empty()||s.len()>160||!s.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'||b==b'_'){Err("invalid_request: Invalid record ID".into())}else{Ok(())}}
pub fn plain(path:&Path)->Result<()> {for p in path.ancestors(){if let Ok(m)=fs::symlink_metadata(p){if crate::code_quality::snapshot::is_link(&m){return Err("storage_error: Linked private storage is not allowed".into())}}}Ok(())}
pub fn read<T:DeserializeOwned>(path:&Path)->Result<T>{plain(path)?;crate::dependency_security::bounded_json(path,MAX_RECORD)?.ok_or_else(||"not_found: Record does not exist".into())}
pub fn atomic(path:&Path,value:&impl Serialize)->Result<()> {plain(path)?;if let Some(p)=path.parent(){fs::create_dir_all(p).map_err(|e|e.to_string())?;}crate::dependency_security::atomic_json(path,value,MAX_RECORD)}
pub fn hash_file(path:&Path)->Result<(String,u64)> {plain(path)?;let mut f=crate::code_quality::snapshot::open_plain(path)?;let mut h=Sha256::new();let mut buf=[0u8;65536];let mut total=0;loop{let n=f.read(&mut buf).map_err(|e|e.to_string())?;if n==0{break}h.update(&buf[..n]);total+=n as u64;}Ok((format!("{:x}",h.finalize()),total))}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct Mutation {pub table:String,pub id:String,pub value:Value}
#[derive(Serialize,Deserialize)]
struct Transaction {job:Job,writes:Vec<Mutation>,activity:Value}
pub struct Store {pub root:PathBuf}
impl Store {
 pub fn new(root:PathBuf)->Self{Self{root}}
 pub fn dir(&self,id:&str)->Result<PathBuf>{crate::dependency_security::validate_id(id)?;let p=self.root.join(id);plain(&p)?;Ok(p)}
 pub fn path(&self,job:&str,table:&str,id:&str)->Result<PathBuf>{safe_id(table)?;safe_id(id)?;Ok(self.dir(job)?.join(table).join(format!("{id}.json")))}
 pub fn get<T:DeserializeOwned>(&self,job:&str,table:&str,id:&str)->Result<T>{read(&self.path(job,table,id)?)}
 pub fn job(&self,id:&str)->Result<Job>{read(&self.dir(id)?.join("job.json"))}
 pub fn for_each(&self,job:&str,table:&str,mut f:impl FnMut(Value)->Result<()>)->Result<()> {safe_id(table)?;let dir=self.dir(job)?.join(table);plain(&dir)?;let entries=match fs::read_dir(dir){Ok(e)=>e,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>return Ok(()),Err(e)=>return Err(e.to_string())};for entry in entries{let entry=entry.map_err(|e|e.to_string())?;if entry.path().extension().and_then(|s|s.to_str())!=Some("json"){continue}f(read(&entry.path())?)?;}Ok(())}
 pub fn page(&self,job:&str,table:&str,offset:usize,limit:usize)->Result<Value>{if !(1..=200).contains(&limit){return Err("invalid_request: Page size must be 1..200".into())}let mut items=Vec::new();let mut total=0usize;self.for_each(job,table,|v|{if total>=offset&&items.len()<limit {items.push(v);}total+=1;Ok(())})?;let next=offset.saturating_add(items.len());Ok(json!({"items":items,"offset":offset,"total":total,"nextOffset":if next<total{Some(next)}else{None}}))}
 pub fn jobs(&self,mut f:impl FnMut(Job)->Result<()>)->Result<()> {plain(&self.root)?;let entries=match fs::read_dir(&self.root){Ok(v)=>v,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>return Ok(()),Err(e)=>return Err(e.to_string())};for entry in entries{let entry=entry.map_err(|e|e.to_string())?;let id=entry.file_name().to_string_lossy().into_owned();if crate::dependency_security::validate_id(&id).is_ok(){match self.job(&id){Ok(job)=>f(job)?,Err(e)if e.starts_with("not_found")=>{},Err(e)=>return Err(e)}}}Ok(())}
 pub fn recover(&self)->Result<()> {plain(&self.root)?;let entries=match fs::read_dir(&self.root){Ok(v)=>v,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>return Ok(()),Err(e)=>return Err(e.to_string())};for e in entries{let e=e.map_err(|e|e.to_string())?;let id=e.file_name().to_string_lossy().into_owned();if crate::dependency_security::validate_id(&id).is_err(){continue}let dir=self.dir(&id)?;let p=dir.join("transaction.json");if p.exists(){let tx:Transaction=read(&p)?;if tx.job.job_id!=id{return Err("storage_error: Transaction identity mismatch".into())}self.apply(&tx)?;fs::remove_file(p).map_err(|e|e.to_string())?;}}Ok(())}
 pub fn commit(&self,job:&Job,writes:Vec<Mutation>,activity:Value)->Result<()> {let tx=Transaction{job:job.clone(),writes,activity};let dir=self.dir(&job.job_id)?;atomic(&dir.join("transaction.json"),&tx)?;self.apply(&tx)?;fs::remove_file(dir.join("transaction.json")).map_err(|e|e.to_string())}
 fn apply(&self,tx:&Transaction)->Result<()> {let id=&tx.job.job_id;for w in &tx.writes{atomic(&self.path(id,&w.table,&w.id)?,&w.value)?;}atomic(&self.dir(id)?.join("job.json"),&tx.job)?;atomic(&self.path(id,"activity",&format!("{:020}",tx.job.revision))?,&tx.activity)}
 fn rel_slot(owner:&str,kind:&str,target:&str)->(String,String){if kind=="reviewedWork"{(format!("rel-reviewedWork-{target}"),owner.to_string())}else{(format!("rel-{owner}-{kind}"),target.to_string())}}
 /// Relations are sharded (by owner and kind; `reviewedWork` by reviewed work for the inverse lookup), so no lookup scans every relation.
 pub fn relation(&self,job:&str,owner:&str,kind:&str,target:&str)->Result<Option<Mutation>> {safe_id(owner)?;safe_id(kind)?;safe_id(target)?;let(table,id)=Self::rel_slot(owner,kind,target);if self.path(job,&table,&id)?.exists(){return Ok(None)}Ok(Some(Mutation{table,id,value:json!({"owner":owner,"kind":kind,"target":target})}))}
 pub fn related(&self,job:&str,owner:&str,kind:&str,mut f:impl FnMut(&str)->Result<()>)->Result<()> {safe_id(owner)?;safe_id(kind)?;if kind=="reviewedWork"{return self.for_each_relation(job,|o,k,t|{if o==owner&&k=="reviewedWork"{f(t)}else{Ok(())}})}self.for_each(job,&format!("rel-{owner}-{kind}"),|v|f(v["target"].as_str().ok_or("storage_error: Invalid relation record")?))}
 /// Owners (documents) that reviewed `target` work; the only indexed inverse lookup.
 pub fn related_inverse(&self,job:&str,kind:&str,target:&str,mut f:impl FnMut(&str)->Result<()>)->Result<()> {if kind!="reviewedWork"{return Err("storage_error: Inverse lookup is indexed for reviewedWork only".into())}safe_id(target)?;self.for_each(job,&format!("rel-reviewedWork-{target}"),|v|f(v["owner"].as_str().ok_or("storage_error: Invalid relation record")?))}
 pub fn relation_exists(&self,job:&str,owner:&str,kind:&str,target:&str)->Result<bool>{safe_id(owner)?;safe_id(kind)?;safe_id(target)?;let(table,id)=Self::rel_slot(owner,kind,target);Ok(self.path(job,&table,&id)?.exists())}
 /// Streams every relation once (all shards), for whole-ledger validation.
 pub fn for_each_relation(&self,job:&str,mut f:impl FnMut(&str,&str,&str)->Result<()>)->Result<()> {let dir=self.dir(job)?;plain(&dir)?;let entries=match fs::read_dir(&dir){Ok(e)=>e,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>return Ok(()),Err(e)=>return Err(e.to_string())};for entry in entries{let entry=entry.map_err(|e|e.to_string())?;let name=entry.file_name().to_string_lossy().into_owned();if !name.starts_with("rel-")||!entry.path().is_dir(){continue}self.for_each(job,&name,|v|{let(Some(o),Some(k),Some(t))=(v["owner"].as_str(),v["kind"].as_str(),v["target"].as_str())else{return Err("storage_error: Malformed relation record".into())};f(o,k,t)})?;}Ok(())}
 pub fn chunk_path(&self,job:&str,revision:&str)->Result<PathBuf>{crate::dependency_security::validate_id(revision)?;Ok(self.dir(job)?.join("chunks").join(revision))}
 pub fn append_chunk(&self,job:&str,revision:&str,offset:u64,text:&str,prefix:&str)->Result<Value>{if text.len()>65536{return Err("invalid_request: Chunk exceeds 64 KiB".into())}let p=self.chunk_path(job,revision)?;plain(&p)?;fs::create_dir_all(p.parent().unwrap()).map_err(|e|e.to_string())?;if !p.exists(){if offset!=0||prefix!=hash(b""){return Err("offset_mismatch: Start revision at byte zero".into())}fs::OpenOptions::new().write(true).create_new(true).open(&p).map_err(|e|e.to_string())?.sync_all().map_err(|e|e.to_string())?;}let (h,n)=hash_file(&p)?;if offset<n{use std::io::{Seek,SeekFrom};let mut f=crate::code_quality::snapshot::open_plain(&p)?;let mut ph=Sha256::new();let mut remain=offset;let mut buf=[0;65536];while remain>0{let take=buf.len().min(remain as usize);let got=f.read(&mut buf[..take]).map_err(|e|e.to_string())?;if got==0{break}ph.update(&buf[..got]);remain-=got as u64;}if format!("{:x}",ph.finalize())!=prefix{return Err("hash_mismatch: Replay prefix changed".into())}f.seek(SeekFrom::Start(offset)).map_err(|e|e.to_string())?;let mut old=vec![0;text.len()];f.read_exact(&mut old).map_err(|e|e.to_string())?;if old!=text.as_bytes(){return Err("hash_mismatch: Chunk replay differs".into())}}else{if offset!=n||prefix!=h{return Err("offset_mismatch: Staged prefix changed".into())}let mut f=fs::OpenOptions::new().append(true).open(&p).map_err(|e|e.to_string())?;f.write_all(text.as_bytes()).and_then(|_|f.sync_all()).map_err(|e|e.to_string())?;}let(h,n)=hash_file(&p)?;Ok(json!({"revisionId":revision,"stagedBytes":n,"stagedHash":h}))}
}
pub fn mutation(table:&str,id:&str,value:&impl Serialize)->Result<Mutation>{safe_id(table)?;safe_id(id)?;Ok(Mutation{table:table.into(),id:id.into(),value:serde_json::to_value(value).map_err(|e|e.to_string())?})}
